## Dragonfly Cloud + SingleStore — Adat Réteg

A Dragonfly Cloud Redis-API-kompatibilis, tehát `ioredis`-szel csatlakozol hozzá caching-re, session-kezelésre és job queue-kra.  A SingleStore SQL + vektor hibrid lekérdezéseket kezel — ideális az Exa keresési eredmények tárolásához és szemantikus visszakereséséhez.[4][3]

```typescript
// lib/db.ts
import { Redis as Dragonfly } from "ioredis";
import mysql from "mysql2/promise";

// Dragonfly Cloud — cache & sessions
export const cache = new Dragonfly({
  host: process.env.DRAGONFLY_HOST!,
  port: 6385,
  username: "default",
  password: process.env.DRAGONFLY_PASSWORD!,
  tls: {},
});

// SingleStore — vektor + SQL
export const singlestore = mysql.createPool({
  host: process.env.SINGLESTORE_HOST!,
  user: process.env.SINGLESTORE_USER!,
  password: process.env.SINGLESTORE_PASSWORD!,
  database: "perplexity_clone",
  ssl: { rejectUnauthorized: true },
});

// Keresési eredmény cache-elése
export async function cacheSearchResult(query: string, result: any, ttl = 3600) {
  await cache.setex(`search:${query}`, ttl, JSON.stringify(result));
}

// Vektor tárolás SingleStore-ban
export async function storeEmbedding(id: string, text: string, vector: number[]) {
  const conn = await singlestore.getConnection();
  await conn.execute(
    "INSERT INTO search_vectors (id, text, embedding) VALUES (?, ?, JSON_ARRAY_PACK(?))",
    [id, text, JSON.stringify(vector)]
  );
  conn.release();
}
```

